import{_ as a,b as t,c as r,g as d}from"./chunks/framework.86O3EbG5.js";const n=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"articles/ai/books/ai-modern-approach-homework/26.md","filePath":"articles/ai/books/ai-modern-approach-homework/26.md"}'),i={name:"articles/ai/books/ai-modern-approach-homework/26.md"};function o(p,e,s,_,h,l){return t(),r("div",null,[...e[0]||(e[0]=[d('<p>基于斯图尔特.罗素《人工智能：现代方法（第4版)）》的第 26 章&lt;机器人学&gt;，根据此章节的重点，并出一些从 基础→进阶→综合 的练习题，能让我将本章的知识串联起来</p><h2 id="一个差速驱动轮式机器人-左右轮速度分别为-v-l-0-5-m-s-v-r-0-7-m-s-轮距-d-0-3-m-。计算机器人的线速度-v-和角速度-ω。公式-v-v-r-v-l-2-ω-v-r-v-l-d。" tabindex="-1">一个差速驱动轮式机器人，左右轮速度分别为 v_l=0.5&quot; m/s&quot; ，v_r=0.7&quot; m/s&quot; ，轮距 d=0.3&quot; m&quot; 。计算机器人的线速度 v 和角速度 ω。公式：v=(v_r+v_l)/2，ω=(v_r-v_l)/d。</h2><h2 id="马尔可夫定位-一维走廊-位置-x∈-0-1-2-3-。初始均匀分布-bel-x-0-25。机器人执行动作-向右移动1格-但实际移动有0-8概率成功-0-1概率不动-0-1概率移动2格-边界停-。写出预测后的信念分布-bel-ˉ-x-忽略观测更新-。计算具体数值。" tabindex="-1">马尔可夫定位：一维走廊，位置 x∈{0,1,2,3}。初始均匀分布 Bel(x)=0.25。机器人执行动作“向右移动1格”，但实际移动有0.8概率成功，0.1概率不动，0.1概率移动2格（边界停）。写出预测后的信念分布 (Bel) ˉ(x)（忽略观测更新）。计算具体数值。</h2><h2 id="配置空间-c-space-一个平面机器人是半径为0-3的圆形-环境中有一个边长为1的方形障碍物-顶点-0-0-到-1-1-。为了将机器人视为点-需要将障碍物膨胀多大-即求c-space障碍物-写出膨胀后的障碍物区域-几何形状-。" tabindex="-1">配置空间（C Space）：一个平面机器人是半径为0.3的圆形，环境中有一个边长为1的方形障碍物（顶点(0,0)到(1,1)）。为了将机器人视为点，需要将障碍物膨胀多大（即求C Space障碍物）？写出膨胀后的障碍物区域（几何形状）。</h2><h2 id="rrt路径规划-在二维位姿空间-单位正方形-0-10-×-0-10-起点-1-1-终点-9-9-。随机采样点-8-2-。假设当前rrt树上有三个节点-a-1-1-b-3-3-c-5-1-。找出距采样点最近的节点-欧氏距离-并从该节点向采样点生长一步-步长δ-2-。写出新节点坐标及添加到树的过程。" tabindex="-1">RRT路径规划：在二维位姿空间（单位正方形 [0,10]×[0,10]），起点(1,1)，终点(9,9)。随机采样点(8,2)。假设当前RRT树上有三个节点：A(1,1), B(3,3), C(5,1)。找出距采样点最近的节点（欧氏距离），并从该节点向采样点生长一步（步长δ=2）。写出新节点坐标及添加到树的过程。</h2><h2 id="pid控制-一个机器人需要保持设定速度-v-des-1-0-m-s。当前速度误差-e-t-0-2-累积误差积分-i-0-5-误差导数-de-dt-0-1。pid系数-k-p-1-0-k-i-0-5-k-d-0-2。计算控制输出-u-t-。" tabindex="-1">PID控制：一个机器人需要保持设定速度 v_des=1.0 m/s。当前速度误差 e(t)=0.2，累积误差积分 I=0.5，误差导数 de/dt=0.1。PID系数 K_p=1.0,K_i=0.5,K_d=0.2。计算控制输出 u(t)。</h2><h2 id="定位方法比较-比较扩展卡尔曼滤波-ekf-和粒子滤波-pf-用于机器人全局定位。" tabindex="-1">定位方法比较：比较扩展卡尔曼滤波（EKF）和粒子滤波（PF）用于机器人全局定位。</h2><p>(1) 简述EKF和PF各自的优缺点（计算复杂度、多峰分布处理、全局定位能力）。 (2) 在机器人起始位置完全未知（均匀分布）的情况下，应选用哪种方法？为什么？ (3) 如果机器人的运动模型和观测模型都是非线性的，EKF需要做什么近似？PF是否需要？</p><h2 id="slam框架-解释slam问题的定义。简述graph‐slam的基本思想-节点表示位姿-边表示约束-优化误差-。相比于ekf‐slam-graph‐slam有什么优势-如大规模地图、计算效率、收敛性" tabindex="-1">SLAM框架：解释SLAM问题的定义。简述Graph‑SLAM的基本思想（节点表示位姿，边表示约束，优化误差）。相比于EKF‑SLAM，Graph‑SLAM有什么优势（如大规模地图、计算效率、收敛性）？</h2><h2 id="路径规划比较-a算法和rrt都可以用于路径规划。" tabindex="-1">路径规划比较：A算法和RRT都可以用于路径规划。</h2><p>(1) 在已知全局地图的环境中，你会选择A还是RRT？为什么？ (2) 如果地图未知，机器人需要在线探索并规划路径，RRT如何扩展（例如RRT）？ (3) 在动态障碍物环境中，如何保证路径的实时性？（例如D Lite）</p><h2 id="自主清扫机器人系统-设计一个家用扫地机器人的核心模块。" tabindex="-1">自主清扫机器人系统：设计一个家用扫地机器人的核心模块。</h2><p>(1) 需要哪些传感器？（至少三种）分别用于什么目的？ (2) 采用什么定位方法（航迹推算+回环检测？SLAM？）说明理由。 (3) 清扫覆盖路径规划算法（如Z字形扫掠、随机覆盖）的优缺点。 (4) 当机器人电量低时如何返回充电座？需要哪些感知和规划？</p>',13)])])}const c=a(i,[["render",o]]);export{n as __pageData,c as default};
